'use strict';
const el=id=>document.getElementById(id);let busy=false,verified=false,data=null,page='Tổng quan',preview=null;
function sync(){if(!auth.active()){auth.clear();verified=false;}document.querySelector('.login-layout').hidden=verified;el('admin').hidden=!verified;el('loginForm').hidden=verified;el('session').hidden=true;if(!verified){data=null;preview=null;el('directory').replaceChildren();el('adminStatus').textContent='';}document.querySelectorAll('button').forEach(b=>b.disabled=busy);}
async function run(fn){if(busy)return;busy=true;sync();try{await fn();}catch(e){(verified?el('adminStatus'):el('status')).textContent='Lỗi: '+e.message;}finally{busy=false;sync();}}
async function load(){el('adminStatus').textContent='Đang tải…';data=await auth.overview();render();el('adminStatus').textContent='Đã tải dữ liệu từ Google Sheets.';}
el('ping').onclick=()=>run(async()=>{const r=await apiRequest();if(!r.ok||r.environment!=='TEST')throw Error('API không ở TEST');el('status').textContent='Kết nối thành công';});
el('loginForm').onsubmit=e=>{e.preventDefault();const k=el('key').value.trim();el('key').value='';run(async()=>{try{await auth.login(k);}catch(e){auth.clear();throw e;}verified=true;page='Tổng quan';sync();window.scrollTo(0,0);await load();});};
el('adminMe').onclick=()=>run(async()=>{await auth.me();el('adminStatus').textContent='Phiên hợp lệ';});el('adminLogout').onclick=()=>run(async()=>{await auth.logout();verified=false;el('status').textContent='Đã đăng xuất';});el('refreshAdmin').onclick=()=>run(load);setInterval(()=>{if(!busy&&verified&&!auth.active()){sync();el('status').textContent='Phiên hết hạn';}},1000);
function node(tag,text,parent,cls){const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;if(parent)parent.append(n);return n;}
function btn(parent,text,fn){const b=node('button',text,parent,'btn secondary');b.type='button';b.onclick=fn;return b;}
const pages=['Tổng quan','Cơ sở','Quản lý lớp','Học sinh','Import Excel','Tài khoản','Phân quyền','Nhật ký','Cấu hình'];
function render(){const root=el('directory');root.replaceChildren();el('nav').replaceChildren();pages.forEach(p=>{const b=btn(el('nav'),({'Tổng quan':'⌂','Cơ sở':'◫','Quản lý lớp':'▤','Học sinh':'♙','Import Excel':'↗','Tài khoản':'♙','Phân quyền':'⚙','Nhật ký':'▤','Cấu hình':'⚙'}[p]||'')+'  '+p,()=>{page=p;preview=null;render();});if(p===page)b.classList.add('selected');});node('h2',page,root);if(!data)return;const f=el('campusFilter').value,g=el('grade').value,s=el('search').value.toLowerCase();const cs=data.campuses.filter(c=>!f||c.id===f),ls=data.classes.filter(c=>(!f||c.campus===f)&&(!g||String(c.grade)===g)),ss=data.students.filter(x=>ls.some(c=>c.id===x.classId));const match=x=>(x.id+' '+x.name).toLowerCase().includes(s);
if(page==='Tổng quan'){const hero=node('section',undefined,root,'hero section');const intro=node('div',undefined,hero);node('div','🌿 Li chào bạn!',intro,'eyebrow');node('h2','Cùng lắng nghe, cùng thấu hiểu.',intro);node('p','Quản trị danh mục hai cơ sở · Chỉ sử dụng dữ liệu giả lập.',intro);const mascot=node('img',undefined,hero);mascot.src='data:image/png;base64,';mascot.alt='Li - người bạn đồng hành';const tiles=node('div',undefined,root,'tiles');for(const [t,n] of [['Cơ sở',cs.length],['Lớp',ls.length],['Học sinh mẫu',ss.length],['Đang hoạt động',ss.filter(x=>x.active).length]]){const tile=node('div',undefined,tiles,'tile');node('strong',n,tile);node('span',t,tile);}for(const c of cs){const l=ls.filter(x=>x.campus===c.id);node('div',c.name+' · '+l.length+' lớp · '+ss.filter(x=>l.some(y=>y.id===x.classId)).length+' học sinh mẫu',root,'tile');}}
else if(page==='Cơ sở')table(root,['Mã','Tên'],cs.map(x=>[x.id,x.name]));else if(page==='Quản lý lớp'||page==='Học sinh'){const kind=page==='Quản lý lớp'?'class':'student';btn(root,'+ Thêm mới',()=>editor(root,kind));const rows=(kind==='class'?ls:ss).filter(match);table(root,kind==='class'?['Mã','Tên','Cơ sở','Khối','Trạng thái','Thao tác']:['Mã','Tên','Lớp','Trạng thái','Thao tác'],rows.map(x=>[x.id,x.name,...(kind==='class'?[x.campus,x.grade]:[x.classId]),x.active?'Hoạt động':'Ngừng',()=>editor(root,kind,x)]));}else if(page==='Import Excel')importUI(root);else if(page==='Tài khoản')accountUI(root);else if(page==='Phân quyền')permissionUI(root);else node('p','Phân hệ này chưa mở trong TEST2B.',root);}
function table(root,headers,rows){const t=node('table',undefined,node('div',undefined,root,'tablewrap'));const h=t.createTHead().insertRow();headers.forEach(x=>node('th',x,h));const b=t.createTBody();rows.forEach(row=>{const tr=b.insertRow();row.forEach(v=>{const td=tr.insertCell();if(typeof v==='function')btn(td,'Sửa',v);else td.textContent=v;});});}
function field(form,label,value,options){const l=node('label',label,form);const n=node(options?'select':'input',undefined,l);if(options)options.forEach(([v,t])=>{const o=node('option',t,n);o.value=v;});n.value=value??'';return n;}
function editor(root,kind,x){root.querySelector('.editor')?.remove();const form=node('form',undefined,root,'editor');root.prepend(form);const id=field(form,'Mã TEST',x?.id||(kind==='class'?'TEST_CLASS_':'TEST_STUDENT_'));id.readOnly=!!x;const name=field(form,'Tên giả lập (Mẫu …)',x?.name||'Mẫu ');const a=kind==='class'?field(form,'Cơ sở',x?.campus||'TSC',data.campuses.map(c=>[c.id,c.name])):field(form,'Lớp',x?.classId||data.classes[0]?.id,data.classes.map(c=>[c.id,c.name]));const grade=kind==='class'?field(form,'Khối',x?.grade||6,[6,7,8,9].map(n=>[n,n])):null;const active=field(form,'Trạng thái',String(x?.active??true),[['true','Hoạt động'],['false','Ngừng']]);const save=node('button','Lưu',form,'btn');save.type='submit';btn(form,'Hủy',()=>form.remove());form.onsubmit=e=>{e.preventDefault();const item={id:id.value.trim(),name:name.value.trim(),active:active.value==='true',...(kind==='class'?{campus:a.value,grade:Number(grade.value)}:{classId:a.value})};run(async()=>{await auth.save(kind,x?'edit':'create',[item]);await load();});};}
function parseCSV(text){const rows=[];let row=[],v='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){v+='"';i++;}else quoted=!quoted;}else if(c===','&&!quoted){row.push(v);v='';}else if(c==='\n'&&!quoted){row.push(v.replace(/\r$/,''));rows.push(row);row=[];v='';}else v+=c;}if(quoted)throw Error('CSV thiếu dấu ngoặc kép');if(v||row.length){row.push(v.replace(/\r$/,''));rows.push(row);}return rows;}
function importUI(root){node('p','Nhập CSV UTF-8 xuất từ Excel. Tối đa 100 học sinh giả lập/lần. Chỉ thêm mới.',root);btn(root,'Tải CSV mẫu',()=>{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob(['\ufeffMã học sinh,Mã lớp,Tên hiển thị,Đang hoạt động\nTEST_STUDENT_NEW1,TEST_CLASS_1,Mẫu 01,Có\n'],{type:'text/csv;charset=utf-8'}));a.download='Danh_sach_hoc_sinh_mau.csv';a.click();URL.revokeObjectURL(a.href);});const file=node('input',undefined,root);file.type='file';file.accept='.csv';const out=node('div',undefined,root);file.onchange=async()=>{out.replaceChildren();preview=null;try{if(!file.files[0]||file.files[0].size>100000)throw Error('File quá lớn hoặc chưa chọn');const rows=parseCSV((await file.files[0].text()).replace(/^\ufeff/,''));const header=rows.shift()?.map(v=>v.trim()).join(',');if(!['student_id,class_id,display_name,active','Mã học sinh,Mã lớp,Tên hiển thị,Đang hoạt động'].includes(header))throw Error('Sai tiêu đề CSV. Hãy sử dụng file mẫu.');const seen=new Set(data.students.map(x=>x.id));const errors=[];const items=rows.filter(r=>r.some(Boolean)).map((r,i)=>{const [id,classId,name,rawActive]=r.map(v=>v.trim());const active=({'có':'TRUE','không':'FALSE','đang hoạt động':'TRUE','ngừng hoạt động':'FALSE'})[rawActive?.toLowerCase()]||rawActive?.toUpperCase();if(r.length!==4||!/^TEST_STUDENT_[A-Z0-9_]{1,40}$/.test(id)||seen.has(id)||!data.classes.some(c=>c.id===classId)||!/^Mẫu [\p{L}\p{N} _.-]{1,70}$/u.test(name)||!['TRUE','FALSE'].includes(active))errors.push('Dòng '+(i+2)+': mã trùng hoặc dữ liệu không hợp lệ');seen.add(id);return {id,classId,name,active:active==='TRUE'};});if(!items.length||items.length>100)errors.push('Cần 1–100 dòng');table(out,['Mã','Lớp','Tên','Hoạt động'],items.map(x=>[x.id,x.classId,x.name,x.active?'Có':'Không']));errors.forEach(e=>node('p',e,out));if(!errors.length){preview=items;btn(out,'Xác nhận lưu '+items.length+' học sinh',()=>run(async()=>{await auth.save('student','create',items);preview=null;page='Học sinh';await load();}));}}catch(e){node('p',e.message,out);}};}
['campusFilter','grade','search'].forEach(id=>el(id).oninput=render);sync();

const accountRoles=[['STUDENT','Học sinh'],['TEACHER','Giáo viên'],['COUNSELOR','Chuyên viên tâm lý'],['ADMIN','Quản trị viên']];
function accountUI(root){node('p','TEST2C.2 · Tài khoản giả lập, chưa có quyền đăng nhập. TEST_ADMIN được bảo vệ.',root);const role=field(root,'Vai trò','',[['','Tất cả'],...accountRoles]);const state=field(root,'Trạng thái','',[['','Tất cả'],['true','Hoạt động'],['false','Đã khóa']]);btn(root,'+ Thêm tài khoản',()=>accountEditor(root));btn(root,'Tạo tài khoản học sinh còn thiếu',()=>{const linked=new Set(data.accounts.map(a=>a.studentId));const items=data.students.filter(s=>s.active&&!linked.has(s.id)).slice(0,100).map(s=>({id:s.id.replace(/^TEST_STUDENT_/,'TEST_USER_'),role:'STUDENT',studentId:s.id,active:true}));if(!items.length){el('adminStatus').textContent='Không có học sinh cần tạo tài khoản';return;}if(confirm('Tạo '+items.length+' tài khoản giả lập?'))run(async()=>{await auth.saveAccounts('create',items);await load();});});const out=node('div',undefined,root);function draw(){out.replaceChildren();const f=el('campusFilter').value,g=el('grade').value,search=el('search').value.toLowerCase();const rows=data.accounts.filter(a=>{const st=data.students.find(s=>s.id===a.studentId),cl=data.classes.find(c=>c.id===st?.classId);return (!role.value||a.role===role.value)&&(!state.value||String(a.active)===state.value)&&(!f||cl?.campus===f)&&(!g||String(cl?.grade)===g)&&(a.id+' '+(st?.name||'')).toLowerCase().includes(search);});table(out,['Mã tài khoản','Vai trò','Mã học sinh','Trạng thái','Thao tác'],rows.map(a=>[a.id,accountRoles.find(r=>r[0]===a.role)?.[1]||a.role,a.studentId||'—',a.active?'Hoạt động':'Đã khóa',a.id==='TEST_ADMIN'?'Được bảo vệ':()=>accountEditor(root,a)]));}role.onchange=state.onchange=draw;draw();}
function accountEditor(root,a){root.querySelector('.editor')?.remove();const form=node('form',undefined,root,'editor');root.prepend(form);const id=field(form,'Mã tài khoản',a?.id||'TEST_USER_');id.readOnly=!!a;const role=field(form,'Vai trò',a?.role||'STUDENT',accountRoles);const student=field(form,'Học sinh liên kết',a?.studentId||'',[['','—'],...data.students.map(s=>[s.id,s.id+' · '+s.name])]);const active=field(form,'Trạng thái',String(a?.active??true),[['true','Hoạt động'],['false','Đã khóa']]);function update(){student.disabled=role.value!=='STUDENT';if(student.disabled)student.value='';}role.onchange=update;update();const save=node('button','Lưu',form,'btn');save.type='submit';btn(form,'Hủy',()=>form.remove());form.onsubmit=e=>{e.preventDefault();run(async()=>{await auth.saveAccounts(a?'edit':'create',[{id:id.value.trim(),role:role.value,studentId:role.value==='STUDENT'?student.value:'',active:active.value==='true'}]);await load();});};}

const capLabels={DIRECTORY_VIEW:'Xem danh mục',DIRECTORY_EDIT:'Sửa danh mục',STATS_VIEW:'Xem thống kê',SURVEY_MANAGE:'Quản lý khảo sát',ACCOUNT_MANAGE:'Quản lý tài khoản',PERMISSION_MANAGE:'Quản lý phân quyền',AUDIT_VIEW:'Xem nhật ký',DATA_EXPORT:'Xuất dữ liệu',SURVEY_APPROVE:'Phê duyệt khảo sát'};
const scopeLabels={SCHOOL:'Toàn trường',CAMPUS:'Cơ sở',GRADE:'Khối theo cơ sở',CLASS:'Lớp'};
function permissionUI(root){
 node('p','TEST2C.2 · Cấp quyền giả lập. Không cấp quyền đọc nội dung tư vấn. Các quyền chưa mở đăng nhập thực tế.',root);
 const accounts=data.accounts.filter(a=>a.id!=='TEST_ADMIN'&&a.role!=='STUDENT'&&a.active);
 const form=node('form',undefined,root,'editor');
 const user=field(form,'Tài khoản','',[['','Chọn tài khoản'],...accounts.map(a=>[a.id,a.id+' · '+(accountRoles.find(r=>r[0]===a.role)?.[1]||a.role)])]);
 const scope=field(form,'Phạm vi','CLASS',Object.entries(scopeLabels));const target=field(form,'Đối tượng','',[]);const cap=field(form,'Quyền thao tác','',[]);
 function options(n,arr){n.replaceChildren();arr.forEach(([v,t])=>{const o=node('option',t,n);o.value=v;});}
 function update(){const a=accounts.find(a=>a.id===user.value);const admin=a?.role==='ADMIN';scope.options[0].disabled=!admin;if(!admin&&scope.value==='SCHOOL')scope.value='CLASS';const cs=data.campuses.filter(c=>c.active),ls=data.classes.filter(c=>c.active&&cs.some(b=>b.id===c.campus));const grades=[...new Set(ls.map(c=>c.campus+':'+c.grade))];options(target,scope.value==='SCHOOL'?[['ALL','Toàn trường']]:scope.value==='CAMPUS'?cs.map(c=>[c.id,c.name]):scope.value==='GRADE'?grades.map(g=>[g,g]):ls.map(c=>[c.id,c.name+' · '+c.campus]));const keys=admin?Object.keys(capLabels).filter(k=>scope.value==='SCHOOL'||!['ACCOUNT_MANAGE','PERMISSION_MANAGE','AUDIT_VIEW'].includes(k)):['DIRECTORY_VIEW','STATS_VIEW','SURVEY_MANAGE'];options(cap,keys.map(k=>[k,capLabels[k]]));}
 user.onchange=scope.onchange=update;update();const save=node('button','Cấp quyền',form,'btn');save.type='submit';form.onsubmit=e=>{e.preventDefault();run(async()=>{await auth.permission('savePermission',{mode:'grant',item:{userId:user.value,scope:scope.value,scopeId:target.value,capability:cap.value}});await load();});};
 const filter=field(root,'Lọc theo tài khoản','',[['','Tất cả'],...data.accounts.filter(a=>a.id!=='TEST_ADMIN').map(a=>[a.id,a.id])]);const out=node('div',undefined,root);function draw(){out.replaceChildren();const t=node('table',undefined,node('div',undefined,out,'tablewrap'));const h=t.createTHead().insertRow();['Tài khoản','Phạm vi','Đối tượng','Quyền','Trạng thái','Thao tác'].forEach(x=>node('th',x,h));const b=t.createTBody();(data.permissions||[]).filter(p=>!filter.value||p.userId===filter.value).forEach(p=>{const tr=b.insertRow();[p.userId,scopeLabels[p.scope]||p.scope,p.scopeId,capLabels[p.capability]||p.capability,p.active?'Đang cấp':'Đã thu hồi'].forEach(v=>tr.insertCell().textContent=v);const td=tr.insertCell();if(p.active)btn(td,'Thu hồi',()=>{if(confirm('Thu hồi quyền này?'))run(async()=>{await auth.permission('savePermission',{mode:'revoke',item:{id:p.id}});await load();});});});}filter.onchange=draw;draw();
 node('h3','Kiểm tra quyền tại Backend',root);const test=node('div',undefined,root,'editor');const tu=field(test,'Tài khoản','',[['','Chọn tài khoản'],...data.accounts.filter(a=>a.id!=='TEST_ADMIN').map(a=>[a.id,a.id])]);const tc=field(test,'Lớp','',data.classes.map(c=>[c.id,c.name+' · '+c.campus]));const tk=field(test,'Quyền','DIRECTORY_VIEW',Object.entries(capLabels).filter(([k])=>!['ACCOUNT_MANAGE','PERMISSION_MANAGE','AUDIT_VIEW'].includes(k)));const result=node('p','Chưa kiểm tra',test);btn(test,'Kiểm tra',()=>run(async()=>{const r=await auth.permission('checkPermission',{userId:tu.value,classId:tc.value,capability:tk.value});result.textContent=r.allowed?'ĐƯỢC PHÉP (giả lập)':'TỪ CHỐI (giả lập)';}));
}
